"""Kaggle cell: bounded1000-step train/validation-only GPU experiment; verify free quota before submitting."""
import hashlib,json,os,pathlib,shutil,subprocess,sys
EXPECTED_BUNDLE_MANIFEST='286d44fc6140be8493165122e6187670c61e432a1533a2e58398707f76076ac9'
# Accelerator must be explicitly selected after verifying free quota.
import torch
if not torch.cuda.is_available(): raise RuntimeError('GPU experiment requires CUDA; refusing CPU fallback')
print({'cuda':torch.version.cuda,'gpu':torch.cuda.get_device_name(0)},flush=True)
venv=pathlib.Path('/tmp/indic-adaptation-env')
subprocess.run([sys.executable,'-m','venv','--without-pip','--system-site-packages',str(venv)],check=True,timeout=120)
runtime=str(venv/'bin/python')
subprocess.run([runtime,'-m','pip','install','-q','transformers==4.51.3','lightning==2.6.6','torchdata==0.11.0','sentencepiece','safetensors==0.8.0','IndicTransToolkit==1.1.1','sacrebleu==2.6.0'],check=True,timeout=600)
source=next(p.parent for p in pathlib.Path('/kaggle/input').rglob('BUNDLE_MANIFEST.json') if hashlib.sha256(p.read_bytes()).hexdigest()==EXPECTED_BUNDLE_MANIFEST)
manifest=json.loads((source/'BUNDLE_MANIFEST.json').read_text())
root=pathlib.Path('/tmp/indic-adaptation-source')
root.mkdir(exist_ok=True)
if any('test.jsonl' in n or 'in22' in n.lower() for n in manifest['files']): raise ValueError('Held-out data forbidden in training bundle')
for name,digest in manifest['files'].items():
    path=source/name
    assert hashlib.sha256(path.read_bytes()).hexdigest()==digest,'Input hash mismatch'
    target=root/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(path,target)
# Verify and cache private upstream input; no online Hub access or token needed.
snapshot_source=next(pathlib.Path('/kaggle/input').rglob('PINNED_SNAPSHOT.json')).parent
snapshot=json.loads((snapshot_source/'PINNED_SNAPSHOT.json').read_text())
assert snapshot['revision']=='2cfd0a20057756d756bf3e53528f492afc52f91a'
os.environ['HF_HUB_CACHE']='/tmp/indic-hf-cache'
os.environ['HF_HUB_OFFLINE']='1'
os.environ['TRANSFORMERS_OFFLINE']='1'
cache=pathlib.Path(os.environ['HF_HUB_CACHE'])/'models--ai4bharat--indictrans2-en-indic-dist-200M'/'snapshots'/snapshot['revision']
cache.mkdir(parents=True,exist_ok=True)
for name,digest in snapshot['files'].items():
    path=snapshot_source/name
    assert hashlib.sha256(path.read_bytes()).hexdigest()==digest,'Pinned snapshot hash mismatch'
    shutil.copyfile(path,cache/name)
# Explicit reviewed trainer override; source digest retained with outputs.
import base64
trainer_source=base64.b64decode('')
assert hashlib.sha256(trainer_source).hexdigest()=='614ec60cf9d8c5fed20fb88b7b24eaa45452fc5479cc650f6b9a719c6cfe46ae'
(root/'scripts/train-indictrans2-lightning.py').write_bytes(trainer_source)
pathlib.Path('/kaggle/working/trainer-source.py').write_bytes(trainer_source)
# Test actual periodic state restoration before spending the larger budget.
fixture=pathlib.Path('/tmp/indic-recovery-fixture')
fixture_args=[runtime,'-u',str(root/'scripts/train-indictrans2-lightning.py'),'--output',str(fixture),'--batch-size','1','--fixture-rows','2','--accelerator','gpu','--seed','42','--recovery-every-steps','1','--learning-rate','2e-6']
subprocess.run(fixture_args+['--max-steps','2'],cwd=root,check=True,timeout=600)
assert (fixture/'recovery/latest.ckpt').is_file(),'No periodic checkpoint'
subprocess.run(fixture_args+['--max-steps','4','--resume',str(fixture/'recovery/latest.ckpt')],cwd=root,check=True,timeout=600)
fixture_result=json.loads((fixture/'result.json').read_text())
assert fixture_result['steps']==4,'Resume did not reach expected step'
pathlib.Path('/kaggle/working/recovery-fixture-result.json').write_text(json.dumps(fixture_result,indent=2)+'\n')
shutil.rmtree(fixture) # Disposable fixture created above; leave real model outputs intact.

out=pathlib.Path('/kaggle/working/indic-controlled-1000steps-seed42')
print('Starting1000-step controlled GPU adaptation: seed42, batch2, validation only',flush=True)
base=[runtime,'-u',str(root/'scripts/train-indictrans2-lightning.py'),'--output',str(out),'--batch-size','2','--accelerator','gpu','--max-steps','1000','--seed','42','--recovery-every-steps','100','--learning-rate','2e-6']
subprocess.run(base,cwd=root,check=True,timeout=3600)
print('Optimizer run completed; starting complete internal validation generation',flush=True)
subprocess.run([runtime,'-u',str(root/'scripts/validate-indictrans2-generation.py'),'--export-dir',str(out/'export'),'--sample-size','412','--output','/kaggle/working/indic-controlled-validation-seed42'],cwd=root,check=True,timeout=900)
print('Pilot and internal generation completed; no production or public release approval',flush=True)
